{
  "name": "express-sitemap-xml",
  "description": "Express middleware to serve `sitemap.xml` from a list of URLs",
  "version": "3.1.0",
  "author": {
    "name": "Feross Aboukhadijeh",
    "email": "feross@feross.org",
    "url": "https://feross.org"
  },
  "bugs": {
    "url": "https://github.com/feross/express-sitemap-xml/issues"
  },
  "dependencies": {
    "p-memoize": "^4.0.1",
    "xmlbuilder": "^15.1.1"
  },
  "devDependencies": {
    "common-tags": "^1.8.0",
    "standard": "*",
    "tape": "^5.0.1"
  },
  "homepage": "https://github.com/feross/express-sitemap-xml",
  "keywords": [
    "express",
    "google",
    "serve sitemap",
    "serve sitemap.xml",
    "site map",
    "site map xml",
    "sitemap",
    "sitemap generator",
    "sitemap xml",
    "sitemap.xml",
    "sitemaps",
    "xml"
  ],
  "license": "MIT",
  "main": "index.js",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/feross/express-sitemap-xml.git"
  },
  "scripts": {
    "test": "standard && tape test/**/*.js"
  },
  "funding": [
    {
      "type": "github",
      "url": "https://github.com/sponsors/feross"
    },
    {
      "type": "patreon",
      "url": "https://www.patreon.com/feross"
    },
    {
      "type": "consulting",
      "url": "https://feross.org/support"
    }
  ]
}

{
  "name": "buffer",
  "description": "Node.js Buffer API, for the browser",
  "version": "6.0.3",
  "author": {
    "name": "Feross Aboukhadijeh",
    "email": "feross@feross.org",
    "url": "https://feross.org"
  },
  "bugs": {
    "url": "https://github.com/feross/buffer/issues"
  },
  "contributors": [
    "Daniel Cousens",
    "Romain Beauxis <toots@rastageeks.org>",
    "James Halliday <mail@substack.net>"
  ],
  "dependencies": {
    "base64-js": "^1.3.1",
    "ieee754": "^1.2.1"
  },
  "devDependencies": {
    "airtap": "^3.0.0",
    "benchmark": "^2.1.4",
    "browserify": "^17.0.0",
    "concat-stream": "^2.0.0",
    "hyperquest": "^2.1.3",
    "is-buffer": "^2.0.5",
    "is-nan": "^1.3.0",
    "split": "^1.0.1",
    "standard": "*",
    "tape": "^5.0.1",
    "through2": "^4.0.2",
    "uglify-js": "^3.11.5"
  },
  "homepage": "https://github.com/feross/buffer",
  "jspm": {
    "map": {
      "./index.js": {
        "node": "@node/buffer"
      }
    }
  },
  "keywords": [
    "arraybuffer",
    "browser",
    "browserify",
    "buffer",
    "compatible",
    "dataview",
    "uint8array"
  ],
  "license": "MIT",
  "main": "index.js",
  "types": "index.d.ts",
  "repository": {
    "type": "git",
    "url": "https://github.com/feross/buffer.git"
  },
  "scripts": {
    "perf": "browserify --debug perf/bracket-notation.js > perf/bundle.js && open perf/index.html",
    "perf-node": "node perf/bracket-notation.js && node perf/concat.js && node perf/copy-big.js && node perf/copy.js && node perf/new-big.js && node perf/new.js && node perf/readDoubleBE.js && node perf/readFloatBE.js && node perf/readUInt32LE.js && node perf/slice.js && node perf/writeFloatBE.js && node perf/write-hex.js",
    "size": "browserify -r ./ | uglifyjs -c -m | gzip | wc -c",
    "standard": "standard",
    "test": "tape test/*.js test/node/*.js",
    "test-browser-old": "airtap -- test/*.js",
    "test-browser-old-local": "airtap --local -- test/*.js",
    "test-browser-new": "airtap -- test/*.js test/node/*.js",
    "test-browser-new-local": "airtap --local -- test/*.js test/node/*.js",
    "update-authors": "./bin/update-authors.sh"
  },
  "standard": {
    "ignore": [
      "test/node/**/*.js",
      "test/common.js",
      "test/_polyfill.js",
      "perf/**/*.js"
    ]
  },
  "funding": [
    {
      "type": "github",
      "url": "https://github.com/sponsors/feross"
    },
    {
      "type": "patreon",
      "url": "https://www.patreon.com/feross"
    },
    {
      "type": "consulting",
      "url": "https://feross.org/support"
    }
  ]
}

